ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "query": {
    "insert": "MDM_INTERACCIONES",
    "documents": [
      {
        "Fecha_Interaccion": {
          "\$date": payload.interaction.interactionDate
        },
        "Tipo_Documento": payload.retentionCustomer.documentType,
        "Numero_Identificacion": payload.retentionCustomer.documentNumber,
        "Nombre_Cliente": payload.retentionCustomer.names,
        "Tipo_Interaccion": payload.interaction.interactionType,
        "SubTipo_Interaccion": payload.interaction.interactionSubType,
        "Agente": payload.interaction.agent,
        "Nombre_Agente": payload.interaction.agentName,
        "Canal": payload.interaction.channel,
        "Observacion": payload.interaction.observation,
        "Reincidente": payload.interaction.recurrent,
        "NumeroConexion": payload.interaction.connectionNumber,
        "Portal_Origen": payload.interaction.sourcePortal
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
    (status: "OK") if (payload.codigo? and payload.codigo == 200),
    (code: payload.codigo as Number) if (payload.codigo?),
    (message: {
        (message: payload.mensaje) if (payload.mensaje?)
    }) if (payload.mensaje?)
}

