%dw 2.0
output application/json
---
{
  "query": {
    "insert": "MDM_JOURNEY_COMERCIAL_CLIENTE",
    "documents": [
      {
        "cliente": {
          "tipoDocumento": payload.retentionCustomer.documentType,
          "numeroDocumento": payload.retentionCustomer.documentNumber,
          "correoUsuario": payload.retentionCustomer.email,
          "correoNotificacion": payload.journey.notificationEmail
        },
        "servicioVigente": {
          "producto": (payload.journey.currentService.products default []) map (item) -> {
            "idBundle": item.bundleId,
            "idAuxiliar": item.auxiliaryId,
            "svaOtt": (item.svaOtt default []) map (sva) -> {
              "id": sva.id
            }
          },
          "fechaActivacion": payload.retentionService.serviceStartDate,
          "ctaServicio": payload.retentionService.serviceAccountId,
          "ctaFacturacion": payload.retentionService.billingAccount,
          "ultimoTramite": payload.journey.currentService.lastTransaction,
          "estado": payload.journey.currentService.status
        },
        "tramitesComerciales": {
          "activacion": payload.journey.commercialTransactions.activation default [],
          "cambioPlan": payload.journey.commercialTransactions.planChange default [],
          "fidelizacion": payload.journey.commercialTransactions.loyalty default [],
          "retencion": payload.journey.commercialTransactions.retention default [],
          "cancelacion": (payload.journey.commercialTransactions.cancellation default []) map (item) -> {
            "idBundle": item.bundleId,
            "idAuxiliar": item.auxiliaryId,
            "svaOtt": item.svaOtt,
            "numeroOrden": item.orderNumber,
            "cuentaServicio": item.serviceAccountId,
            "fechaRegistro": item.registrationDate,
            "fechaProgramada": item.scheduledDate,
            "fechaEjecucion": item.executionDate,
            "fechaDesactivacion": item.deactivationDate,
            "estado": item.status,
            "tecnologia": item.technology,
            "canal": item.channel,
            "resultado": item.result
          }
        },
        "interacciones": (payload.journey.interactions default []) map (item) -> {
          "tipoInteraccion": item.interactionType,
          "detalleInteraccion": item.interactionDetail,
          "canal": item.channel,
          "correlationId": item.correlationId,
          "fechaInteraccion": item.interactionDate
        },
        "auditoria": (payload.journey.audit default []) map (item) -> {
          "tramite": item.transaction,
          "fechaRegistro": item.registrationDate,
          "fechaModificacion": item.modificationDate,
          "aplicacion": item.application
        },
        "fechaRegistro": payload.creationDate,
        "fechaModificacion": payload.modificationDate
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
    (status: "OK") if (payload.codigo? and payload.codigo == 200),
    (code: payload.codigo as Number) if (payload.codigo?),
    (message: {
        (message: payload.mensaje) if (payload.mensaje?)
    }) if (payload.mensaje?)
}

%dw 2.0
output application/json
var response1 = payload."0".payload default {}
var response2 = payload."1".payload default {}
var success1 = (response1.code default 500) as Number == 200
var success2 = (response2.code default 500) as Number == 200
---
{
	code: if ( success1 and success2 ) 200
        else
            400,
	message: if ( success1 and success2 ) "Success"
        else
            "Error processing Mongo operations",
	results: {
		interaction: {
			code: response1.code,
			message: response1.message
		},
		journey: {
			code: response2.code,
			message: response2.message
		}
	}
}

%dw 2.0
output application/json
---
{
    (status: "OK") if (payload.codigo? and payload.codigo == 200),
    (code: payload.codigo as Number) if (payload.codigo?),
    (message: {
        (message: payload.mensaje) if (payload.mensaje?),
        (retentionNumber: payload.numeroRetencion) if (payload.numeroRetencion?)
    }) if (payload.mensaje? or payload.numeroRetencion?)
}

%dw 2.0
output application/json
---
{
    status: payload.codigo as Number,
    code: "Ok",
    message: {
        message: payload.mensaje default ""
    },
    messageServer: payload.numeroRetencion default "",
    cause: [
        {
            origin: "",
            message: ""
        }
    ]
}
